2	// Pure parser for inline link parentheticals at the end of a spec.md statement (spec-test-coverage v3 §Decisions): trailing `([label](path#Lline), ...)`, split into test links (VALIDATED_BY) vs code links (IMPLEMENTED_BY).
3	import { posix } from "node:path";
4	import { isTestFile, isDocFile } from "./test-paths.js";
5	import { segmentStatements } from "./spec-segment.js";
6	/** Strip a leading `./` or `/` so repo-root-relative and dot-relative forms match. */
7	export function normalizePath(path) {
8	    return path.replace(/^\.?\/+/, "");
9	}
10	// A `../`-climbing href is relative to the spec's own directory (as GitHub renders it), resolved against dirname(specPath); both the graph binder and the require-spec-link ESLint index resolve through here so they agree.
11	export function resolveLinkPath(linkPath, specPath) {
12	    const stripped = linkPath.startsWith("./") ? linkPath.slice(2) : linkPath;
13	    if (stripped.startsWith("../")) {
14	        return posix.normalize(posix.join(posix.dirname(specPath), stripped));
15	    }
16	    return normalizePath(linkPath);
17	}
18	const LINK_INSIDE_PAREN_RE = /\[([^\]]+)\]\(([^)]+)\)/g;
19	function trimTrailingSpaceAndPeriod(s) {
20	    let end = s.length;
21	    while (end > 0 && /[\s.]/.test(s[end - 1])) {
22	        end--;
23	    }
24	    return end;
25	}
26	// Walks backward counting paren depth (a naive `\(([^()]*)\)` regex fails since markdown links themselves contain `()`).
27	function matchingOpenParen(s, end) {
28	    let depth = 1;
29	    for (let i = end - 2; i >= 0; i--) {
30	        const c = s[i];
31	        if (c === ")") {
32	            depth++;
33	            continue;
34	        }
35	        if (c !== "(") {
36	            continue;
37	        }
38	        depth--;
39	        if (depth === 0) {
40	            return { open: i, innerStart: i + 1, innerEnd: end - 1 };
41	        }
42	    }
43	    return null;
44	}
45	function findTrailingParenSpan(s) {
46	    const end = trimTrailingSpaceAndPeriod(s);
47	    if (end === 0 || s[end - 1] !== ")") {
48	        return null;
49	    }
50	    return matchingOpenParen(s, end);
51	}
52	/** Turn a `[label](path#Lline)` regex match into a normalized link ref. */
53	function linkRefFromMatch(match) {
54	    const label = match[1].replace(/\s+/g, " ").trim();
55	    const href = match[2].trim();
56	    const hashIdx = href.indexOf("#L");
57	    const rawPath = hashIdx >= 0 ? href.slice(0, hashIdx) : href;
58	    const path = rawPath.replace(/^\/+/, "");
59	    let line = null;
60	    if (hashIdx >= 0) {
61	        const n = Number(href.slice(hashIdx + 2));
62	        line = Number.isFinite(n) ? n : null;
63	    }
64	    return { label, path, line };
65	}
66	function parseLinksInStatement(statement, keepPath) {
67	    const span = findTrailingParenSpan(statement);
68	    if (span === null) {
69	        return [];
70	    }
71	    const inner = statement.slice(span.innerStart, span.innerEnd);
72	    const refs = [];
73	    for (const match of inner.matchAll(LINK_INSIDE_PAREN_RE)) {
74	        const ref = linkRefFromMatch(match);
75	        if (keepPath(ref.path)) {
76	            refs.push(ref);
77	        }
78	    }
79	    return refs;
80	}
81	/** Keeps only links whose path is a test file (VALIDATED_BY edges). */
82	export function parseTestLinksInStatement(statement) {
83	    return parseLinksInStatement(statement, isTestFile);
84	}
85	/** Keeps only source-code links — excludes test files and prose docs (so ADR/docs `.md` refs don't become IMPLEMENTED_BY links). */
86	export function parseCodeLinksInStatement(statement) {
87	    return parseLinksInStatement(statement, (path) => !isTestFile(path) && !isDocFile(path));
88	}
89	// Excludes absolute URLs and placeholder shapes (`path/to/test.ts`, `<owner>`-style segments) that spec prose uses to document the link convention itself.
90	const NON_REPO_PATH_RE = /^[a-z][a-z0-9+.-]*:|^path(\/|#|$)|[<>]/i;
91	// Flags would-be VALIDATED_BY test links in a NON-trailing parenthetical (used by the validate cron); scans only text before the trailing paren, with inline code spans stripped first.
92	export function findMisplacedCoverageLinks(statement) {
93	    const span = findTrailingParenSpan(statement);
94	    const trailingOpen = span ? span.open : statement.length;
95	    const scannable = statement.slice(0, trailingOpen).replace(/`[^`]*`/g, "");
96	    const refs = [];
97	    for (const match of scannable.matchAll(LINK_INSIDE_PAREN_RE)) {
98	        const ref = linkRefFromMatch(match);
99	        if (!isTestFile(ref.path) || NON_REPO_PATH_RE.test(ref.path)) {
100	            continue;
101	        }
102	        refs.push(ref);
103	    }
104	    return refs;
105	}
106	/** Shared loop behind both the validate cron and the web-ui coverage derivation. */
107	export function linksForStatements(content) {
108	    return segmentStatements(content).map((statement) => ({
109	        statement,
110	        testLinks: parseTestLinksInStatement(statement.text),
111	    }));
112	}
